css:
/* Modales (Login & Perfil B2B) */
.saas-modal-overlay { position: fixed; inset: 0; background: rgba(10, 34, 64, 0.6); backdrop-filter: blur(5px); z-index: 3000; display: flex; align-items: center; justify-content: center; padding: 20px; opacity: 1; transition: opacity 0.3s ease; }
.saas-modal-overlay.hidden { opacity: 0; pointer-events: none; }
.saas-modal-card { background: #FFFFFF; width: 100%; max-width: 440px; border-radius: 24px; padding: 40px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25); position: relative; transform: translateY(0); transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1); border: 1px solid #E2E8F0; }
.saas-modal-overlay.hidden .saas-modal-card { transform: translateY(30px); }

.close-modal-btn { position: absolute; top: 20px; right: 20px; background: transparent; border: none; font-size: 1.8rem; color: #94a3b8; cursor: pointer; transition: color 0.2s; line-height: 1; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; border-radius: 50%; }
.close-modal-btn:hover { color: #A81200; background: #fef2f2; }

/* Login Modal */
.modal-header-center { text-align: center; margin-bottom: 20px; }
.modal-logo-clean { height: 75px; margin-bottom: 15px; object-fit: contain; }
.modal-header-center h2 { font-size: 1.8rem; font-weight: 900; color: #0A2240; margin-bottom: 10px; letter-spacing: -0.5px; }
.modal-header-center p { font-size: 0.95rem; color: #64748B; line-height: 1.5; }
.secure-badge { display: flex; justify-content: center; align-items: center; gap: 6px; margin-top: 25px; font-size: 0.8rem; color: #94a3b8; font-weight: 600; }
.secure-badge svg { width: 14px; height: 14px; }

/* Perfil B2B Modal */
.profile-card { max-width: 480px; padding: 0; overflow: hidden;}
.profile-header { background: #f8fafc; padding: 30px; display: flex; align-items: center; gap: 20px; border-bottom: 1px solid #E2E8F0; }
.profile-avatar-img { width: 64px; height: 64px; border-radius: 50%; object-fit: cover; box-shadow: 0 4px 10px rgba(10,34,64,0.1); border: 2px solid #FFFFFF; background: #E2E8F0;}
.profile-info h2 { font-size: 1.25rem; font-weight: 800; color: #0F172A; margin-bottom: 2px; line-height: 1.2; word-break: break-word;}
.user-email { font-size: 0.9rem; color: #64748b; font-weight: 500; }

.reorder-section { padding: 30px; }
.reorder-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
.reorder-header h3 { font-size: 1.05rem; font-weight: 800; color: #0A2240; text-transform: uppercase; }

.order-list-preview { background: #f8fafc; border: 1px solid #E2E8F0; border-radius: 12px; padding: 15px 20px; margin-bottom: 25px; }
.order-list-preview ul { list-style: none; display: flex; flex-direction: column; gap: 8px; padding: 0; margin: 0; }
.order-list-preview li { display: flex; align-items: center; gap: 8px; font-size: 0.95rem; color: #0F172A; font-weight: 500; }
.order-list-preview li svg { width: 16px; color: #10b981; }

.logout-wrapper { padding: 0 30px 25px; display: flex; justify-content: center; }
.btn-logout { background: transparent; border: none; color: #94a3b8; font-size: 0.9rem; font-weight: 600; cursor: pointer; text-decoration: underline; transition: color 0.2s;}
.btn-logout:hover { color: #A81200; }

/* Icono Navbar Logueado Global */
.icon-btn.logged-in { border-color: #25D366 !important; background: rgba(37, 211, 102, 0.1) !important; position: relative; }
.icon-btn.logged-in::after { content: ''; position: absolute; top: 0px; right: 0px; width: 12px; height: 12px; background: #25D366; border-radius: 50%; border: 2px solid #16365C; z-index: 2;}
.nav-user-avatar { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; display: none; }
.icon-btn.logged-in .nav-user-avatar { display: block; }
.icon-btn.logged-in svg { display: none; }

/* Toasts Globales */
.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: 3000; display: flex; flex-direction: column; gap: 10px; pointer-events: none; }
.toast { background: rgba(10, 34, 64, 0.95); backdrop-filter: blur(10px); color: #FFFFFF; padding: 14px 28px; border-radius: 50px; font-size: 0.95rem; font-weight: 600; box-shadow: 0 10px 30px rgba(0,0,0,0.3); display: flex; align-items: center; gap: 12px; animation: toastSlideUp 0.3s ease forwards; border: 1px solid rgba(255,255,255,0.1); }
.toast svg { width: 20px; color: #25D366; }
.toast.fade-out { animation: toastFadeOut 0.4s ease forwards; }
@keyframes toastSlideUp { from { opacity: 0; transform: translateY(30px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toastFadeOut { to { opacity: 0; transform: translateY(-15px) scale(0.9); } }


/* =========================================
   0. BANNER FULL BLEED
   ========================================= */
.hero-banner-image {
    width: 100vw;
    margin-left: calc(-50vw + 50%); 
    margin-top: -60px; /* <--- ESTA LÍNEA SUBE EL BANNER PARA PEGARLO AL MENÚ */
    margin-bottom: 40px;
    display: block;
}
.hero-banner-image img {
    width: 100%;
    height: auto;
    display: block;
    object-fit: cover;
}
/* =========================================
   1. VARIABLES Y BASE B2B
   ========================================= */
:root {
    --zarco-blue: #0A2240; 
    --zarco-blue-light: #16365C; 
    --zarco-blue-glass: rgba(10, 34, 64, 0.95); 
    --zarco-red: #A81200; 
    --zarco-red-dark: #7A0A00; 
    --white: #FFFFFF; 
    --wa-green: #10B981; 
    --wa-green-dark: #059669;
    --bg-dashboard: #F4F7F9; 
    --border-soft: #E2E8F0;
    --text-main: #0F172A;
    --text-muted: #64748B;
    --transition-fast: 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { overflow-x: hidden; scroll-behavior: smooth; }
body.bg-dashboard { font-family: 'Inter', sans-serif; color: var(--text-main); background-color: var(--bg-dashboard); }

.desktop-only { display: block; } 
.mobile-only { display: none; }
.text-red { color: var(--zarco-red); }
.text-right { justify-content: flex-end !important; text-align: right !important; }
.text-center { justify-content: center !important; text-align: center !important; }
.hidden { display: none !important; }

.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.6s var(--expo), transform 0.6s var(--expo); }
.reveal.active { opacity: 1; transform: translateY(0); }
.stagger-1 { transition-delay: 0.1s; } 
.stagger-2 { transition-delay: 0.2s; } 

/* =========================================
   2. DASHBOARD HEADER Y CONTROLES (SE MANTIENE)
   ========================================= */
.dashboard-wrapper { max-width: 1440px; margin: 0 auto; padding: 240px 5% 150px 5%; }
.dash-header { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 40px; }
.dash-title { font-size: 3.5rem; font-weight: 900; color: var(--zarco-blue); letter-spacing: -1.5px; margin-bottom: 8px; line-height: 1; }
.dash-desc { color: var(--text-muted); font-size: 1.15rem; margin: 0; font-weight: 500; max-width: 700px; }

.status-box { display: flex; flex-direction: column; align-items: flex-end; }
.status-indicator { display: inline-flex; align-items: center; gap: 10px; background: #ecfdf5; color: #059669; padding: 8px 16px; border-radius: 50px; font-weight: 800; font-size: 0.85rem; letter-spacing: 1px; border: 1px solid #a7f3d0; margin-bottom: 8px; }
.pulse { width: 10px; height: 10px; background-color: #10b981; border-radius: 50%; animation: pulse-ring 2s infinite; }
@keyframes pulse-ring { 0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4); } 70% { box-shadow: 0 0 0 8px rgba(16, 185, 129, 0); } 100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); } }
.status-text { font-size: 0.9rem; color: #94a3b8; font-weight: 600; }

.command-bar-wrapper { margin-bottom: 30px; }
.control-bar { background: var(--white); padding: 30px; border-radius: 16px; box-shadow: 0 4px 10px rgba(0,0,0,0.02); display: flex; flex-direction: column; gap: 20px; border: 1px solid var(--border-soft); }
.search-module { position: relative; width: 100%; }
.search-icon { position: absolute; left: 25px; top: 50%; transform: translateY(-50%); width: 24px; height: 24px; color: #9ca3af; transition: color 0.3s; }
.search-input { width: 100%; padding: 22px 25px 22px 65px; background: #F8FAFC; border: 2px solid transparent; border-radius: 12px; font-size: 1.1rem; font-family: 'Inter', sans-serif; color: var(--zarco-blue); font-weight: 600; transition: all var(--transition-fast); }
.search-input:focus { outline: none; border-color: var(--zarco-red); background: var(--white); box-shadow: 0 0 0 4px rgba(168, 18, 0, 0.08); }
.search-input:focus + .search-icon { color: var(--zarco-red); }
.search-input::placeholder { color: #94A3B8; font-weight: 400; }
.search-hint { position: absolute; right: 20px; top: 50%; transform: translateY(-50%); background: #E2E8F0; color: #475569; padding: 6px 12px; border-radius: 6px; font-size: 0.75rem; font-weight: 800; letter-spacing: 1px; pointer-events: none; text-transform: uppercase; }

.advanced-filters { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.filter-group { display: flex; flex-direction: column; gap: 8px; }
.filter-group label { font-size: 0.75rem; font-weight: 800; color: #64748b; text-transform: uppercase; letter-spacing: 1px; padding-left: 5px; }

.select-wrapper { position: relative; }
.select-wrapper svg { position: absolute; right: 15px; top: 50%; transform: translateY(-50%); width: 18px; height: 18px; color: #64748b; pointer-events: none; }
.saas-select { width: 100%; appearance: none; background: #F8FAFC; border: 1px solid var(--border-soft); padding: 14px 45px 14px 20px; border-radius: 10px; font-family: 'Inter', sans-serif; font-size: 1rem; font-weight: 600; color: var(--zarco-blue); cursor: pointer; transition: all 0.2s ease; }
.saas-select:hover, .saas-select:focus { border-color: var(--zarco-blue); outline: none; background: var(--white); }

.filter-module { width: 100%; margin-top: 10px; overflow: hidden; }
.filter-track { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 5px; -ms-overflow-style: none; scrollbar-width: none; }
.filter-track::-webkit-scrollbar { display: none; }
.filter-pill { flex-shrink: 0; padding: 10px 24px; border-radius: 50px; background: #F8FAFC; border: 1px solid var(--border-soft); color: #64748b; font-family: 'Inter', sans-serif; font-weight: 700; font-size: 0.95rem; cursor: pointer; transition: all var(--transition-fast); }
.filter-pill:hover { border-color: var(--zarco-blue); color: var(--zarco-blue); }
.filter-pill.active { background: var(--zarco-blue); color: var(--white); border-color: var(--zarco-blue); box-shadow: 0 4px 15px rgba(10, 34, 64, 0.2); }

/* =========================================
   3. TABLA DE CATÁLOGO (ESTILO APPLE / SAAS)
   ========================================= */
.catalog-section { margin-bottom: 50px; }
.catalog-section.active { opacity: 1 !important; transform: translateY(0) !important; }
.catalog-container { width: 100%; display: flex; flex-direction: column; gap: 12px; }

.catalog-table-wrapper {
    background: var(--white);
    border: 1px solid var(--border-soft);
    border-radius: 16px;
    box-shadow: 0 4px 10px rgba(0,0,0,0.02);
    overflow: hidden; 
}

.catalog-grid-layout { display: grid; grid-template-columns: 50px 100px 3.5fr 1.5fr 80px 120px 160px; gap: 15px; align-items: center; width: 100%; }

.catalog-header-master { 
    background: #F8FAFC; 
    border-bottom: 1px solid var(--border-soft); 
    padding: 16px 24px; 
}
.h-col { font-size: 0.75rem; font-weight: 800; color: #64748B; text-transform: uppercase; letter-spacing: 1px; }

.catalog-body { display: flex; flex-direction: column; width: 100%; }

.catalog-item-row { 
    background: var(--white); 
    border-bottom: 1px solid var(--border-soft); 
    padding: 16px 24px; 
    transition: background 0.2s ease; 
    cursor: pointer; 
}
.catalog-item-row:last-child { border-bottom: none; }
.catalog-item-row:hover { background-color: #F8FAFC; }
.catalog-item-row.selected { background: #F0Fdf4; }

.col-check { display: flex; align-items: center; justify-content: center; }
.native-checkbox { appearance: none; -webkit-appearance: none; width: 22px; height: 22px; margin: 0; border: 2px solid #cbd5e1; border-radius: 6px; background: var(--white); cursor: pointer; display: grid; place-content: center; transition: all 0.2s ease; pointer-events: none; }
.native-checkbox::before { content: ""; width: 10px; height: 10px; transform: scale(0); transition: 120ms transform ease-in-out; box-shadow: inset 1em 1em white; background-color: white; transform-origin: center; clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%); }
.catalog-item-row:hover .native-checkbox { border-color: var(--zarco-blue); }
.native-checkbox:checked { background-color: var(--zarco-blue); border-color: var(--zarco-blue); }
.native-checkbox:checked::before { transform: scale(1); }

.col-sku { font-family: monospace; color: #94a3b8; font-size: 0.9rem; font-weight: 600; }
.col-desc { font-weight: 800; font-size: 1.05rem; color: var(--zarco-blue); line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.highlight-text { background-color: #fef08a; color: #b45309; padding: 0 2px; border-radius: 2px; }

.cat-badge { display: inline-flex; align-items: center; padding: 6px 12px; border-radius: 6px; font-size: 0.7rem; font-weight: 800; text-transform: uppercase; letter-spacing: 1px; }
.cat-lacteos { background: #e0f2fe; color: #0369A1; } 
.cat-embutidos { background: #ffe4e6; color: #BE123C; } 
.cat-abarrotes { background: #BEDBB9; color: #038B20; } 
.cat-gourmet { background: #fef3c7; color: #047857; } 

.badge-unit { font-family: monospace; background: #f1f5f9; color: #475569; padding: 6px 12px; border-radius: 6px; font-size: 0.8rem; font-weight: 700; border: 1px solid #e2e8f0; display: inline-block;}

.col-price { display: flex; align-items: center; justify-content: flex-end; }
.price-value { font-size: 1.2rem; font-weight: 900; color: var(--zarco-red); letter-spacing: -0.5px; font-family: 'Inter', sans-serif; }

.col-action { display: flex; align-items: center; justify-content: center; }
.inline-action-group {
    display: flex;
    align-items: center;
    gap: 4px;
    background: #F1F5F9;
    padding: 4px;
    border-radius: 8px;
    border: 1px solid transparent;
    transition: border 0.2s;
    width: 100%;
}
.inline-action-group:hover { border-color: #CBD5E1; }
.inline-qty-input {
    width: 40px;
    text-align: center;
    background: transparent;
    border: none;
    font-weight: 700;
    font-size: 0.95rem;
    color: var(--zarco-blue);
    -moz-appearance: textfield;
}
.inline-qty-input:focus { outline: none; background: var(--white); border-radius: 4px; box-shadow: 0 0 0 2px rgba(10,34,64,0.1); }
.inline-qty-input::-webkit-outer-spin-button, .inline-qty-input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }

.btn-inline-add { 
    flex: 1;
    background: var(--white); 
    border: 1px solid #CBD5E1; 
    color: var(--zarco-blue); 
    padding: 8px 0; 
    border-radius: 6px; 
    font-family: 'Inter', sans-serif; 
    font-weight: 800; 
    font-size: 0.75rem; 
    letter-spacing: 0.5px; 
    cursor: pointer; 
    transition: all 0.2s ease; 
    box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}
.inline-action-group:hover .btn-inline-add:not(.added) { border-color: var(--zarco-blue); }
.btn-inline-add.added { background: var(--wa-green) !important; border-color: var(--wa-green) !important; color: var(--white) !important; }

.skeleton-row { align-items: center; cursor: default; pointer-events: none;}
.skeleton-box { height: 20px; background: #e2e8f0; border-radius: 4px; position: relative; overflow: hidden; }
.skeleton-box::after { content: ''; position: absolute; inset: 0; transform: translateX(-100%); background-image: linear-gradient(90deg, rgba(255,255,255,0) 0, rgba(255,255,255,0.5) 20%, rgba(255,255,255,0.5) 60%, rgba(255,255,255,0)); animation: shimmer 1.5s infinite; }
@keyframes shimmer { 100% { transform: translateX(100%); } }
.state-cell { text-align: center; padding: 60px 20px; background: var(--white); color: #64748b; font-weight: 600; font-size: 1.1rem; }

.pagination-bar { display: flex; justify-content: space-between; align-items: center; padding: 20px; background: var(--white); border-radius: 12px; border: 1px solid var(--border-soft); margin-top: 10px; box-shadow: 0 4px 10px rgba(0,0,0,0.02); }
.results-info { color: #64748b; font-weight: 600; font-size: 0.95rem; }
.page-controls { display: flex; align-items: center; gap: 15px; }
.btn-page { width: 44px; height: 44px; border-radius: 10px; border: 1px solid #cbd5e1; background: var(--white); display: flex; align-items: center; justify-content: center; cursor: pointer; color: var(--zarco-blue); transition: all 0.2s ease; }
.btn-page svg { width: 22px; height: 22px; }
.btn-page:hover:not(:disabled) { border-color: var(--zarco-blue); color: var(--white); background: var(--zarco-blue); box-shadow: 0 4px 10px rgba(10,34,64,0.2); }
.btn-page:disabled { opacity: 0.4; cursor: not-allowed; }
.page-numbers { font-weight: 800; color: var(--zarco-blue); font-size: 1rem; min-width: 60px; text-align: center; }

/* =========================================
   4. CARRITO LATERAL (SAAS GLASSMORPHISM)
   ========================================= */
.cart-fab { position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%); background: var(--zarco-blue); color: var(--white); border: none; border-radius: 50px; padding: 14px 28px; display: flex; align-items: center; gap: 15px; cursor: pointer; box-shadow: 0 10px 25px rgba(10,34,64,0.4); z-index: 2050; transition: all 0.4s var(--expo); border: 1px solid rgba(255,255,255,0.1); white-space: nowrap;}
.cart-fab:hover { transform: translate(-50%, -5px) scale(1.02); background: var(--zarco-blue-light); box-shadow: 0 15px 35px rgba(10,34,64,0.5); }
.cart-fab.hidden { opacity: 0; transform: translate(-50%, 50px); pointer-events: none; }
.fab-icon { position: relative; display: flex; align-items: center; justify-content: center; }
.fab-icon svg { width: 24px; height: 24px; }
.fab-badge { position: absolute; top: -8px; right: -12px; background: var(--zarco-red); color: var(--white); font-size: 0.75rem; font-weight: 900; width: 20px; height: 20px; border-radius: 50%; display: flex; align-items: center; justify-content: center; border: 2px solid var(--zarco-blue); }
.fab-total { font-size: 1.15rem; font-weight: 900; letter-spacing: 0.5px; border-left: 1px solid rgba(255,255,255,0.2); padding-left: 15px; }

.cart-overlay { position: fixed; inset: 0; background: rgba(10,34,64,0.4); backdrop-filter: blur(4px); z-index: 99998; transition: opacity 0.4s ease; opacity: 1; }
.cart-overlay.hidden { opacity: 0; pointer-events: none; }

.cart-drawer { position: fixed; top: 0; right: 0; width: 100%; max-width: 480px; height: 100vh; background: rgba(255, 255, 255, 0.97); backdrop-filter: blur(25px); z-index: 99999; display: flex; flex-direction: column; box-shadow: -10px 0 50px rgba(0,0,0,0.15); border-left: 1px solid rgba(0,0,0,0.05); transition: transform 0.5s var(--expo); transform: translateX(0); }
.cart-drawer.hidden { transform: translateX(100%); }

.cart-header { padding: 40px 30px 25px; border-bottom: 1px solid rgba(0,0,0,0.06); display: flex; justify-content: space-between; align-items: flex-start; background: transparent; }
.cart-header-titles { width: 100%; }
.header-titles-flex { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; }
.cart-header-titles h2 { font-size: 1.6rem; font-weight: 900; color: var(--zarco-blue); letter-spacing: -0.5px; margin: 0;}
.btn-clear-cart { background: none; border: none; color: var(--zarco-red); font-size: 0.8rem; font-weight: 800; text-transform: uppercase; letter-spacing: 1px; cursor: pointer; transition: 0.2s; padding-right: 15px;}
.btn-clear-cart:hover { opacity: 0.7; text-decoration: underline; }
.cart-header-titles p { font-size: 0.95rem; color: var(--text-muted); margin: 0; }
.cart-close-btn { background: #F1F5F9; border: none; font-size: 1.5rem; color: var(--text-muted); cursor: pointer; width: 36px; height: 36px; border-radius: 50%; transition: all 0.2s; display: flex; align-items: center; justify-content: center; flex-shrink: 0;}
.cart-close-btn:hover { background: #FEF2F2; color: var(--zarco-red); transform: rotate(90deg); }

.cart-progress-wrapper { padding: 20px 30px; background: rgba(248, 250, 252, 0.8); border-bottom: 1px solid rgba(0,0,0,0.06); }
.cart-progress-text { font-size: 0.85rem; font-weight: 800; color: var(--zarco-blue); margin-bottom: 8px; display: flex; justify-content: space-between; }
.cart-progress-bar { width: 100%; height: 8px; background: #E2E8F0; border-radius: 10px; overflow: hidden; }
.cart-progress-fill { height: 100%; background: var(--wa-green); width: 0%; transition: width 0.6s var(--expo); }

.cart-body { flex: 1; overflow-y: auto; padding: 10px 30px; display: flex; flex-direction: column; background: transparent; }
.cart-empty-state { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; color: #94A3B8; padding: 40px 20px; }
.cart-empty-state svg { width: 60px; height: 60px; margin-bottom: 15px; color: #CBD5E1; stroke-width: 1; }
.cart-empty-state p { font-size: 1.2rem; font-weight: 800; color: var(--zarco-blue); margin-bottom: 5px; }

.cart-item { display: flex; flex-direction: column; padding: 25px 0; border-bottom: 1px solid rgba(0,0,0,0.06); background: transparent; transition: all 0.4s ease; transform-origin: left center; }
.cart-item.removing { opacity: 0; transform: translateX(-30px) scale(0.95); margin-top: -80px; padding: 0; border: none; }

.c-item-top { display: flex; justify-content: space-between; align-items: flex-start; width: 100%; margin-bottom: 15px; }
.c-item-info { flex: 1; padding-right: 15px; }
.c-item-name { display: block; font-size: 1rem; font-weight: 800; color: var(--zarco-blue); line-height: 1.3; margin-bottom: 4px; }
.c-item-price { font-size: 0.95rem; color: var(--text-muted); font-weight: 600; }

.c-item-remove { background: transparent; border: none; color: #CBD5E1; cursor: pointer; transition: color 0.2s; flex-shrink: 0; padding: 5px; margin-top: -5px; }
.c-item-remove svg { width: 22px; height: 22px; }
.c-item-remove:hover { color: var(--zarco-red); }

.c-item-bottom { display: flex; justify-content: space-between; align-items: center; width: 100%; }

.c-item-controls { display: flex; align-items: center; gap: 4px; background: #F1F5F9; border-radius: 50px; padding: 4px; border: 1px solid rgba(0,0,0,0.04); }
.qty-btn { background: var(--white); border: none; width: 30px; height: 30px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; color: var(--zarco-blue); box-shadow: 0 2px 5px rgba(0,0,0,0.06); transition: all 0.2s; }
.qty-btn svg { width: 14px; height: 14px; stroke-width: 3; }
.qty-btn:hover { background: var(--zarco-blue); color: var(--white); }

.qty-input { width: 45px; text-align: center; font-weight: 800; color: var(--zarco-blue); border: none; background: transparent; font-size: 1rem; font-family: 'Inter', sans-serif; -moz-appearance: textfield; padding: 4px 0; }
.qty-input::-webkit-outer-spin-button, .qty-input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.qty-input:focus { outline: none; background: var(--white); border-radius: 8px; box-shadow: 0 0 0 2px rgba(10,34,64,0.1); }

.c-item-total { font-weight: 900; color: var(--zarco-blue); font-size: 1.15rem; letter-spacing: -0.5px; }

.cart-footer { padding: 30px 30px 40px 30px; background: rgba(255,255,255,0.9); border-top: 1px solid rgba(0,0,0,0.06); }
.cart-summary { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 25px; }
.cart-summary span { font-size: 0.9rem; font-weight: 800; color: var(--text-muted); text-transform: uppercase; letter-spacing: 1px; }
.cart-summary h3 { font-size: 2.2rem; font-weight: 900; color: var(--zarco-blue); margin: 0; line-height: 1; letter-spacing: -1px; }

.btn-whatsapp-checkout { width: 100%; background: var(--zarco-blue); color: var(--white); padding: 20px; border-radius: 16px; border: none; font-size: 1.05rem; font-weight: 800; letter-spacing: 0.5px; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 12px; transition: all 0.3s; box-shadow: 0 10px 30px rgba(10,34,64,0.2); }
.btn-whatsapp-checkout svg { width: 22px; height: 22px; fill: currentColor; }
.btn-whatsapp-checkout:hover:not(:disabled) { transform: translateY(-3px); box-shadow: 0 15px 35px rgba(10,34,64,0.3); background: var(--zarco-blue-light); }
.btn-whatsapp-checkout:disabled { background: #E2E8F0; box-shadow: none; cursor: not-allowed; color: #94A3B8; }

/* =========================================
   5. TOASTS Y MODAL AUTH
   ========================================= */
.saas-modal-overlay { position: fixed; inset: 0; background: rgba(10, 34, 64, 0.6); backdrop-filter: blur(5px); z-index: 3000; display: flex; align-items: center; justify-content: center; padding: 20px; opacity: 1; transition: opacity 0.3s ease; }
.saas-modal-overlay.hidden { opacity: 0; pointer-events: none; }
.saas-modal-card { background: var(--white); width: 100%; max-width: 440px; border-radius: 24px; padding: 40px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25); position: relative; transform: translateY(0); transition: transform 0.4s var(--expo); border: 1px solid var(--border-soft); }

/* TOAST ABAJO A LA IZQUIERDA EN DESKTOP (BLINDADO) */
.toast-container { position: fixed; bottom: 30px !important; left: 30px !important; top: auto !important; right: auto !important; transform: none !important; z-index: 4000; display: flex; flex-direction: column-reverse; gap: 10px; pointer-events: none; align-items: flex-start;}
.toast { background: var(--zarco-blue-glass); backdrop-filter: blur(10px); color: var(--white); padding: 14px 24px; border-radius: 12px; font-size: 0.95rem; font-weight: 600; box-shadow: 0 10px 30px rgba(0,0,0,0.3); display: flex; align-items: center; gap: 12px; border: 1px solid rgba(255,255,255,0.1); animation: toastSlideUp 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.toast svg { width: 20px; color: var(--wa-green); flex-shrink: 0; }
.toast.fade-out { animation: toastFadeOutBottom 0.3s forwards; }
@keyframes toastSlideUp { from { opacity: 0; transform: translateY(30px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toastFadeOutBottom { to { opacity: 0; transform: translateY(15px) scale(0.9); } }

/* =========================================
   6. RESPONSIVIDAD MÓVIL BLINDADA
   ========================================= */
@media (max-width: 1024px) {
    /* Ajuste de margen en móvil si es necesario */
    .hero-banner-image { margin-top: -40px; }

    .dashboard-wrapper { padding-top: 160px; padding-bottom: 40px; }
    .dash-header { flex-direction: column; align-items: flex-start; gap: 10px; margin-bottom: 25px; }
    .dash-title { font-size: 2.2rem; }

    .control-bar { padding: 20px; border-radius: 12px; }
    .search-input { padding: 16px 20px 16px 50px; font-size: 1rem; border-radius: 10px; }
    .advanced-filters { grid-template-columns: 1fr; gap: 15px; }
    .filter-module { width: calc(100% + 40px); margin-left: -20px; padding: 0 20px; }
    .filter-track { padding: 5px 0 10px 0; }

    /* EN MÓVIL, LA TABLA SE ADAPTA A UNA LISTA LIMPIA */
    .catalog-header-master { display: none !important; }
    .catalog-table-wrapper { border: none; box-shadow: none; border-radius: 0; background: transparent; }
    .catalog-item-row { 
        display: flex !important; 
        flex-wrap: wrap;
        justify-content: space-between;
        align-items: center;
        padding: 20px; 
        background: var(--white); 
        border-radius: 16px; 
        border: 1px solid var(--border-soft); 
        margin-bottom: 15px; 
        position: relative;
    }

    .col-cat { width: 100%; margin-bottom: 10px; order: 1; }
    .col-check { position: absolute; top: 20px; right: 20px; z-index: 2; }

    .col-desc { width: 100%; order: 2; margin-bottom: 5px; padding-right: 35px; border: none; padding-left: 0; }
    .col-desc strong { font-size: 1.15rem; color: var(--zarco-blue); line-height: 1.4; display: block; white-space: normal;}

    .col-sku { width: 100%; order: 3; margin-bottom: 15px; font-size: 0.85rem; color: #94a3b8; }

    .col-price { width: 45%; order: 4; display: flex !important; flex-direction: column; align-items: flex-start !important; border-top: 1px dashed var(--border-soft); padding-top: 15px; }
    .col-price::before { content: "PRECIO"; font-size: 0.65rem; color: #94A3B8; letter-spacing: 1px; margin-bottom: 2px; }
    .price-value { font-size: 1.4rem; margin: 0; display: block;}

    .col-action { width: 55%; order: 5; display: flex !important; justify-content: flex-end; align-items: center; border-top: 1px dashed var(--border-soft); padding-top: 15px; }
    .col-unit { display: none !important;}

    .cart-fab { bottom: 20px; left: 50%; transform: translateX(-50%); width: auto; padding: 14px 24px; }
    .cart-fab.hidden { transform: translate(-50%, 50px); }
    .cart-fab:hover { transform: translate(-50%, -5px) scale(1.02); }

    .cart-drawer { max-width: 100%; } 
    .pagination-bar { flex-direction: column; gap: 15px; padding: 20px 0; background: transparent; border: none; box-shadow: none;}

    /* TOAST MÓVIL (ARRIBA AL CENTRO) */
    .toast-container { top: 90px !important; bottom: auto !important; right: auto !important; left: 50% !important; transform: translateX(-50%) !important; align-items: center; width: 90%; flex-direction: column; }
    .toast { width: 100%; justify-content: center; border-radius: 50px; animation: toastSlideDown 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
    @keyframes toastSlideDown { from { opacity: 0; transform: translateY(-30px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
    .toast.fade-out { animation: toastFadeOut 0.3s forwards; }
    @keyframes toastFadeOut { to { opacity: 0; transform: translateY(-15px) scale(0.9); } }
}


