let allProducts = [];
let filteredProducts = [];
let currentPage = 1;
const itemsPerPage = 25; 
let currentCategory = 'all';
let searchTerm = '';
let currentSort = 'original'; // <-- Mantendrá tu orden de Excel por defecto
let currentUnit = 'all';

const FREE_SHIPPING_THRESHOLD = 3000; 

// --- VARIABLES DE SESIÓN ---
const savedUserStr = localStorage.getItem('zarcoUser');
const currentUser = savedUserStr ? JSON.parse(savedUserStr) : null;
let clientInfo = { id: "CLI-000", nombre: "Invitado", estatus: "🟢 Contado" };

const savedCart = localStorage.getItem('zarcoCartObjects');
const cart = savedCart ? new Map(JSON.parse(savedCart)) : new Map();

// --- GUARDA LOCAL Y EN LA NUBE ---
function saveCartToStorage() {
    localStorage.setItem('zarcoCartObjects', JSON.stringify(Array.from(cart.entries())));
    if (localStorage.getItem('zarcoUser')) updateCloudCart(); // Revisión en tiempo real
}

// TU NUEVO ENLACE EXACTO
const JSON_URL = 'https://script.google.com/macros/s/AKfycbxw90vbv7D4jNGhOgryf8oj3imRFsiYFVboyWaNbCYS-qC8SnrWzdK-BrDGuNqKxtCZHQ/exec';
const mxnFormatter = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

document.addEventListener('DOMContentLoaded', () => {
    const reveals = document.querySelectorAll('.reveal');
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => { if(entry.isIntersecting) entry.target.classList.add('active'); });
    }, { threshold: 0.1 });
    reveals.forEach(r => observer.observe(r));

    cargarDatosJSON();
    setupCartDrawer();
    setupAuthListeners();

    // Sincronizar al entrar si hay sesión
    if (currentUser) {
        sincronizarConNube();
    }
});

// --- FUNCIONES DE NUBE ---
async function sincronizarConNube() {
    try {
        const response = await fetch(`${JSON_URL}?action=getUserSession&email=${currentUser.email}`);
        const data = await response.json();

        if (data.userData) clientInfo = data.userData;

        if (data.savedCart && data.savedCart !== "[]" && data.savedCart !== "{}" && cart.size === 0) {
            const cloudCartArray = JSON.parse(data.savedCart);
            cloudCartArray.forEach(([id, obj]) => cart.set(id, obj));
            localStorage.setItem('zarcoCartObjects', JSON.stringify(cloudCartArray));
            updateCartUI();
            renderTable();
        }
    } catch (e) { console.log("Modo local activo"); }
}

function updateCloudCart() {
    let checkUser = localStorage.getItem('zarcoUser');
    if (!checkUser) return;
    let activeUser = JSON.parse(checkUser);

    const cartArray = Array.from(cart.entries());
    fetch(JSON_URL, {
        method: 'POST',
        mode: 'no-cors',
        body: JSON.stringify({
            action: "syncCart",
            email: activeUser.email,
            cart: JSON.stringify(cartArray)
        })
    }).catch(e => console.log("Error sync"));
}

function cargarDatosJSON() {
    fetch(JSON_URL + '?action=getInventory')
        .then(response => { 
            if(!response.ok) throw new Error("Error en la descarga."); 
            return response.json(); 
        })
        .then(data => {
            if(data.length > 0 && data[0].error) {
                console.error("Error desde Sheets:", data[0].error);
                throw new Error(data[0].error);
            }

            allProducts = data.map((item, index) => {
                let p = {};
                for (let key in item) {
                    p[String(key).toUpperCase().trim()] = item[key];
                }

                let rawPrice = p["PRECIO FINAL"] || p["PRECIO"] || p["PRECIO MXN"] || "0";
                let cleanPrice = typeof rawPrice === 'string' ? parseFloat(rawPrice.replace(/[^0-9.-]+/g,"")) : parseFloat(rawPrice);
                if (isNaN(cleanPrice)) cleanPrice = 0;

                let catText = String(p["CATEGORÍA"] || p["CATEGORIA"] || "General");
                let prodName = String(p["NOMBRE PARA WEB"] || p["NOMBRE EN BODEGA"] || p["PRODUCTO"] || "Producto Desconocido");
                let skuCode = String(p["SKU"] || p["CÓDIGO"] || p["CODIGO"] || "S/N");
                let unitType = String(p["UNIDAD DE MEDIDA"] || p["UNIDAD"] || p["UND"] || "Pieza");

                return { 
                    id: skuCode, 
                    name: prodName,
                    categoryLabel: catText,
                    categoryId: catText.toLowerCase().replace(/\s+/g, ''),
                    unit: unitType,
                    priceNum: cleanPrice,
                    categoryClass: 'cat-' + catText.toLowerCase().replace(/[^a-z0-9]/g, ''),
                    originalIndex: index 
                };
            });

            allProducts = allProducts.filter(p => p.name !== "Producto Desconocido" && p.priceNum > 0);

            const masterCountEl = document.getElementById('masterCount');
            if(masterCountEl) masterCountEl.innerText = `${allProducts.length} Artículos`;

            const unitSelect = document.getElementById('unitSelect');
            if(unitSelect) {
                unitSelect.innerHTML = '<option value="all">Todas las Unidades</option>';
                const uniqueUnits = [...new Set(allProducts.map(p => p.unit))].filter(Boolean).sort();
                uniqueUnits.forEach(u => {
                    let opt = document.createElement('option');
                    opt.value = u; opt.innerText = u;
                    unitSelect.appendChild(opt);
                });
            }

            applyFilters(); 
            updateCartUI(); 

            const catSec = document.querySelector('.catalog-section');
            if(catSec) catSec.classList.add('active');
        })
        .catch(err => {
            const bodyEl = document.getElementById('productBody');
            const countEl = document.getElementById('masterCount');
            if(bodyEl) bodyEl.innerHTML = `<div class="state-cell" style="width: 100%; color: red;">Fallo de conexión con la matriz. Verifica la consola.</div>`;
            if(countEl) countEl.innerText = "Sistema Fuera de Línea";
            console.error("Error general:", err);
        });
}

function highlightMatch(text, term) {
    if(!term) return text;
    const safeTerm = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(${safeTerm})`, 'gi');
    return String(text).replace(regex, '<span class="highlight-text">$1</span>');
}

function sortData(data) {
    return data.sort((a, b) => {
        if(currentSort === 'original') return a.originalIndex - b.originalIndex;
        if(currentSort === 'name-asc') return String(a.name).localeCompare(String(b.name));
        if(currentSort === 'price-asc') return a.priceNum - b.priceNum;
        if(currentSort === 'price-desc') return b.priceNum - a.priceNum;
        return 0;
    });
}

function applyFilters() {
    const searchInput = document.getElementById('searchInput');
    const sortSelect = document.getElementById('sortSelect');
    const unitSelect = document.getElementById('unitSelect');

    searchTerm = searchInput ? searchInput.value.toLowerCase() : '';
    currentSort = sortSelect ? sortSelect.value : 'original';
    currentUnit = unitSelect ? unitSelect.value : 'all';

    let temp = allProducts.filter(p => {
        const matchText = String(p.name).toLowerCase().includes(searchTerm) || String(p.id).toLowerCase().includes(searchTerm);
        const matchUnit = (currentUnit === 'all') ? true : (p.unit === currentUnit);

        let matchCategory = true;
        if (currentCategory !== 'all') {
            const catExcel = p.categoryLabel.toLowerCase();
            if (currentCategory === 'lacteos') {
                matchCategory = catExcel.includes('queso') || catExcel.includes('crema') || catExcel.includes('lacteo') || catExcel.includes('lácteo') || catExcel.includes('yogurt') || catExcel.includes('mantequilla');
            } else if (currentCategory === 'embutidos') {
                matchCategory = catExcel.includes('carne') || catExcel.includes('embutido') || catExcel.includes('jamon') || catExcel.includes('jamón') || catExcel.includes('salchicha') || catExcel.includes('tocino') || catExcel.includes('pavo');
            } else if (currentCategory === 'abarrotes') {
                matchCategory = catExcel.includes('abarrote') || catExcel.includes('aceite') || catExcel.includes('chile') || catExcel.includes('mayonesa');
            } else if (currentCategory === 'gourmet') {
                matchCategory = catExcel.includes('gourmet') || catExcel.includes('vino') || catExcel.includes('delicatessen') || catExcel.includes('salami');
            } else {
                matchCategory = p.categoryId.includes(currentCategory);
            }
        }

        return matchText && matchCategory && matchUnit;
    });

    filteredProducts = sortData(temp);
    currentPage = 1;
    renderTable();
}

function renderTable() {
    const tbody = document.getElementById('productBody');
    if(!tbody) return;
    tbody.innerHTML = '';

    const start = (currentPage - 1) * itemsPerPage;
    const end = start + itemsPerPage;
    const pageItems = filteredProducts.slice(start, end);

    if(pageItems.length === 0) {
        tbody.innerHTML = `<div class="state-cell" style="width: 100%;">No hay resultados para esta búsqueda.</div>`;
        const resCount = document.getElementById('resultsCount');
        if(resCount) resCount.innerText = "0 resultados";
        return;
    }

    pageItems.forEach((p) => {
        const row = document.createElement('div');
        row.className = 'catalog-item-row catalog-grid-layout';

        let isChecked = cart.has(p.id);
        let currentQty = isChecked ? cart.get(p.id).qty : 1;

        if(isChecked) row.classList.add('selected');

        const highlightedName = highlightMatch(p.name, searchTerm);
        const highlightedSku = highlightMatch(p.id, searchTerm);
        const formattedPrice = mxnFormatter.format(p.priceNum);

        row.innerHTML = `
            <div class="col-check h-col"><div class="custom-checkbox"><input type="checkbox" class="native-checkbox item-checkbox" data-id="${p.id}" data-name="${p.name}" data-price="${p.priceNum}" ${isChecked ? 'checked' : ''}></div></div>
            <div class="col-sku h-col">${highlightedSku}</div>
            <div class="col-desc h-col"><strong>${highlightedName}</strong></div>
            <div class="col-cat h-col"><span class="cat-badge ${p.categoryClass}">${p.categoryLabel}</span></div>
            <div class="col-unit h-col text-center"><span class="badge-unit">${p.unit}</span></div>
            <div class="col-price h-col text-right"><span class="price-value">$ ${formattedPrice}</span></div>
            <div class="col-action h-col text-center">
                <div class="inline-action-group">
                    <input type="number" class="inline-qty-input" value="${currentQty}" min="1">
                    <button class="btn-inline-add ${isChecked ? 'added' : ''}">
                        ${isChecked ? '✓' : '+ AÑADIR'}
                    </button>
                </div>
            </div>
        `;

        row.addEventListener('click', (e) => {
            if (e.target.tagName.toLowerCase() === 'input' || e.target.classList.contains('inline-qty-input')) return;

            const chk = row.querySelector('.item-checkbox');
            const btn = row.querySelector('.btn-inline-add');
            const qtyInput = row.querySelector('.inline-qty-input');

            const isAdding = !cart.has(p.id);
            let qty = parseInt(qtyInput.value) || 1;

            chk.checked = isAdding;
            handleProductSelection(p.id, p.name, p.priceNum, isAdding, row, btn, true, qty);
        });

        const qtyInput = row.querySelector('.inline-qty-input');
        qtyInput.addEventListener('change', (e) => {
            let newQty = parseInt(e.target.value);
            if (isNaN(newQty) || newQty < 1) { newQty = 1; e.target.value = 1; }
            if (cart.has(p.id)) {
                let item = cart.get(p.id);
                item.qty = newQty;
                cart.set(p.id, item);
                saveCartToStorage();
                updateCartUI();
            }
        });

        tbody.appendChild(row);
    });

    let totalPages = Math.ceil(filteredProducts.length / itemsPerPage) || 1;
    const resCount = document.getElementById('resultsCount');
    const pageInfo = document.getElementById('pageInfo');
    const pBtn = document.getElementById('prevBtn');
    const nBtn = document.getElementById('nextBtn');

    if(resCount) resCount.innerText = `Mostrando ${filteredProducts.length} productos`;
    if(pageInfo) pageInfo.innerText = `${currentPage} de ${totalPages}`;
    if(pBtn) pBtn.disabled = currentPage === 1;
    if(nBtn) nBtn.disabled = currentPage >= totalPages;

    const selectAllBtn = document.getElementById('selectAll');
    if (selectAllBtn) selectAllBtn.checked = false;
}

function handleProductSelection(id, name, price, isAdding, row, btn, showToastNotif, qty = 1) {
    if(isAdding) {
        cart.set(id, { name: name, price: parseFloat(price), qty: qty });
        if(row) row.classList.add('selected');
        if(btn) { btn.classList.add('added'); btn.innerHTML = '✓'; }
        if(showToastNotif) showToast(`${qty}x Agregado a la requisición`);
    } else {
        cart.delete(id);
        if(row) row.classList.remove('selected');
        if(btn) { btn.classList.remove('added'); btn.innerHTML = '+ AÑADIR'; }
    }
    saveCartToStorage(); 
    updateCartUI();
}

/* =========================================
   CARRITO LATERAL Y CONEXIÓN A WHATSAPP
   ========================================= */
function setupCartDrawer() {
    const cartFab = document.getElementById('cartFabTrigger');
    const cartDrawer = document.getElementById('cartDrawer');
    const cartOverlay = document.getElementById('cartOverlay');
    const closeCartBtn = document.getElementById('closeCartBtn');
    const btnSendQuote = document.getElementById('btnSendQuote');
    const clearCartBtn = document.getElementById('clearCartBtn');

    function openCart() {
        if(cartDrawer) cartDrawer.classList.remove('hidden');
        if(cartOverlay) cartOverlay.classList.remove('hidden');
        document.body.style.overflow = 'hidden';
    }

    function closeCart() {
        if(cartDrawer) cartDrawer.classList.add('hidden');
        if(cartOverlay) cartOverlay.classList.add('hidden');
        document.body.style.overflow = '';
    }

    if(cartFab) cartFab.addEventListener('click', openCart);
    if(closeCartBtn) closeCartBtn.addEventListener('click', closeCart);
    if(cartOverlay) cartOverlay.addEventListener('click', closeCart);

    if(clearCartBtn) {
        clearCartBtn.addEventListener('click', () => {
            cart.clear();
            saveCartToStorage();
            updateCartUI();
            renderTable(); 
            showToast("Requisición vaciada");
        });
    }

    if(btnSendQuote) {
        btnSendQuote.addEventListener('click', async () => {

            // --- FIX EN TIEMPO REAL PARA VERIFICAR SESIÓN ---
            const checkSession = localStorage.getItem('zarcoUser');
            const activeUser = checkSession ? JSON.parse(checkSession) : null;

            if(!activeUser) {
                showToast("Por favor, inicia sesión para enviar pedidos.");
                closeCart(); // <-- ESTO CIERRA EL CARRITO PARA QUE EL MODAL SE VEA BIEN

                const authModal = document.getElementById('authModal');
                if(authModal) {
                    authModal.classList.remove('hidden');
                    authModal.style.zIndex = '999999'; // <-- ESTO LO FUERZA HASTA ADELANTE

                    // Si el botón de Google sigue invisible, ponemos un mensaje claro
                    const btnContainer = document.getElementById('googleButtonContainer');
                    if(btnContainer && btnContainer.innerHTML.trim() === '') {
                        btnContainer.innerHTML = `<p style="text-align:center; font-size:14px; font-weight:500; color:var(--primary-color);">Cierra esta ventana e inicia sesión usando el botón "RESTAURANTE / INICIAR SESIÓN" en el menú de arriba.</p>`;
                    }
                }
                return;
            }

            // Si llegamos aquí, el usuario sí está logueado
            let userName = clientInfo.nombre !== "Invitado" ? clientInfo.nombre : activeUser.name;
            let userId = clientInfo.id !== "CLI-000" ? clientInfo.id : "CLI-NUEVO";

            let msg = `Hola Matriz El Zarco, soy *${userName}* (${activeUser.email}).\n\nSolicito la cotización formal de la siguiente requisición armada en el Portal B2B:\n\n`;
            let granTotal = 0;
            let itemsForHistory = [];
            let resumenParaNube = "";

            cart.forEach((item, id) => { 
                let totalItem = item.price * item.qty;
                msg += `🔸 ${item.qty}x ${item.name} (Cod: ${id}) - $${mxnFormatter.format(totalItem)}\n`; 
                granTotal += totalItem;
                itemsForHistory.push({ name: item.name, desc: `Cod: ${id}`, qty: item.qty });
                resumenParaNube += `${item.qty}x ${item.name} (${id}), `;
            });

            const formattedTotal = `$${mxnFormatter.format(granTotal)}`;
            msg += `\n*TOTAL ESTIMADO:* ${formattedTotal} MXN\n\nQuedo a la espera de la confirmación operativa.`;

            showToast("Registrando en la Matriz...");

            try {
                const response = await fetch(JSON_URL, {
                    method: 'POST',
                    body: JSON.stringify({
                        action: "saveOrder",
                        clientId: userId,
                        negocio: userName,
                        email: activeUser.email,
                        resumen: resumenParaNube.slice(0, -2),
                        total: granTotal
                    })
                });

                const result = await response.json();
                if(result.status === "Success") {
                    msg = msg.replace("Solicito la cotización", `*REQUISICIÓN ${result.folio}*\n\nSolicito la cotización`);
                }
            } catch (error) {
                console.error("Error al registrar en nube:", error);
            }

            const dateStr = new Date().toLocaleDateString('es-ES', { day: '2-digit', month: 'short', year: 'numeric' });
            const newOrder = {
                folio: `#ZRC-${Math.floor(Math.random() * 9000) + 1000}`,
                date: dateStr,
                total: formattedTotal,
                status: "Procesando",
                items: itemsForHistory
            };

            let currentHistory = JSON.parse(localStorage.getItem('zarco_purchase_history') || '[]');
            currentHistory.unshift(newOrder);
            localStorage.setItem('zarco_purchase_history', JSON.stringify(currentHistory));

            const numeroMatriz = "522298477440"; 
            const waLink = `https://wa.me/${numeroMatriz}?text=${encodeURIComponent(msg)}`;
            window.open(waLink, '_blank');

            cart.clear();
            saveCartToStorage();
            updateCartUI();
            renderTable(); 
            closeCart();
            showToast("Cotización enviada. Revisa tu historial.");
        });
    }
}

window.updateItemQty = function(id, delta) {
    let item = cart.get(id);
    if(item) {
        item.qty += delta;
        if(item.qty <= 0) {
            removeWithAnimation(id);
        } else {
            cart.set(id, item);
            saveCartToStorage();
            updateCartUI();
            updateRowQuantityIfVisible(id, item.qty);
        }
    }
}

window.handleQtyInput = function(id, el) {
    let newQty = parseInt(el.value);
    if (isNaN(newQty) || newQty <= 0) {
        removeWithAnimation(id);
    } else {
        let item = cart.get(id);
        if(item) {
            item.qty = newQty;
            cart.set(id, item);
            saveCartToStorage();
            updateCartUI();
            updateRowQuantityIfVisible(id, newQty);
        }
    }
}

function updateRowQuantityIfVisible(id, newQty) {
    const chk = document.querySelector(`.item-checkbox[data-id="${id}"]`);
    if(chk) {
        const row = chk.closest('.catalog-item-row');
        const input = row.querySelector('.inline-qty-input');
        if(input) input.value = newQty;
    }
}

window.removeWithAnimation = function(id) {
    const cartDomItem = document.getElementById(`cart-item-${id}`);
    if(cartDomItem) {
        cartDomItem.classList.add('removing');
        setTimeout(() => { executeRemove(id); }, 350); 
    } else {
        executeRemove(id);
    }
}

function executeRemove(id) {
    handleProductSelection(id, null, null, false, null, null, false, 1);
    const rows = document.querySelectorAll('.catalog-item-row');
    rows.forEach(row => {
        const chk = row.querySelector('.item-checkbox');
        if(chk && chk.getAttribute('data-id') === id) {
            chk.checked = false;
            row.classList.remove('selected');
            const btn = row.querySelector('.btn-inline-add');
            if(btn) { btn.classList.remove('added'); btn.innerHTML = '+ AÑADIR'; }
        }
    });
}

function updateCartUI() {
    const cartFab = document.getElementById('cartFabTrigger');
    const fabCount = document.getElementById('fabCount');
    const fabTotal = document.getElementById('fabTotal');
    const cartItemsList = document.getElementById('cartItemsList');
    const cartGrandTotal = document.getElementById('cartGrandTotal');
    const btnSendQuote = document.getElementById('btnSendQuote');
    const clearCartBtn = document.getElementById('clearCartBtn');
    const progressWrapper = document.getElementById('progressWrapper');
    const progressText = document.getElementById('progressText');
    const progressFill = document.getElementById('progressFill');

    let totalSum = 0;
    let totalItemsQty = 0; 

    if(cart.size > 0) {
        if(cartFab) cartFab.classList.remove('hidden');
        if(btnSendQuote) btnSendQuote.removeAttribute('disabled');
        if(clearCartBtn) clearCartBtn.classList.remove('hidden');
        if(progressWrapper) progressWrapper.classList.remove('hidden');

        let listHTML = '';
        cart.forEach((item, id) => {
            if(!item.qty) item.qty = 1; 

            let itemTotal = item.price * item.qty;
            totalSum += itemTotal;
            totalItemsQty += item.qty;

            listHTML += `
                <div class="cart-item" id="cart-item-${id}">
                    <div class="c-item-top">
                        <div class="c-item-info">
                            <span class="c-item-name">${item.name}</span>
                            <span class="c-item-price">$${mxnFormatter.format(item.price)} <span style="font-weight: 500; font-size: 0.85rem; color: #94a3b8;">/ un.</span></span>
                        </div>
                        <button class="c-item-remove" onclick="removeWithAnimation('${id}')" title="Quitar">
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                        </button>
                    </div>
                    <div class="c-item-bottom">
                        <div class="c-item-controls">
                            <button class="qty-btn" onclick="updateItemQty('${id}', -1)">
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="5" y1="12" x2="19" y2="12"></line></svg>
                            </button>
                            <input type="number" class="qty-input" value="${item.qty}" min="0" onblur="handleQtyInput('${id}', this)" onkeypress="if(event.key === 'Enter') handleQtyInput('${id}', this)">
                            <button class="qty-btn" onclick="updateItemQty('${id}', 1)">
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
                            </button>
                        </div>
                        <span class="c-item-total">$${mxnFormatter.format(itemTotal)}</span>
                    </div>
                </div>
            `;
        });

        if(cartItemsList) cartItemsList.innerHTML = listHTML;
        if(fabCount) fabCount.innerText = totalItemsQty;

        let progressPct = (totalSum / FREE_SHIPPING_THRESHOLD) * 100;
        if(progressPct >= 100) {
            if(progressFill) {
                progressFill.style.width = '100%';
                progressFill.style.backgroundColor = 'var(--wa-green)';
            }
            if(progressText) progressText.innerHTML = `<span>Envío Mayorista</span> <span style="color: var(--wa-green);">¡Desbloqueado!</span>`;
        } else {
            let faltante = FREE_SHIPPING_THRESHOLD - totalSum;
            if(progressFill) {
                progressFill.style.width = `${progressPct}%`;
                progressFill.style.backgroundColor = 'var(--zarco-blue)';
            }
            if(progressText) progressText.innerHTML = `<span>Te faltan $${mxnFormatter.format(faltante)}</span> <span style="color: var(--text-muted); font-weight:500;">para envío sin costo</span>`;
        }

    } else {
        if(cartFab) cartFab.classList.add('hidden');
        if(btnSendQuote) btnSendQuote.setAttribute('disabled', 'true');
        if(clearCartBtn) clearCartBtn.classList.add('hidden');
        if(progressWrapper) progressWrapper.classList.add('hidden');

        if(cartItemsList) {
            cartItemsList.innerHTML = `
                <div class="cart-empty-state">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="9" cy="21" r="1"></circle><circle cx="20" cy="21" r="1"></circle><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path></svg>
                    <p>Tu requisición está vacía.</p>
                    <span>Agrega productos del inventario para comenzar.</span>
                </div>
            `;
        }
    }

    const formattedTotal = `$${mxnFormatter.format(totalSum)}`;
    if(fabTotal) fabTotal.innerText = formattedTotal;
    if(cartGrandTotal) cartGrandTotal.innerText = formattedTotal;
}

const selectAllCheck = document.getElementById('selectAll');
if (selectAllCheck) {
    selectAllCheck.addEventListener('change', (e) => {
        const isChecked = e.target.checked;
        const rows = document.querySelectorAll('.catalog-item-row:not(.skeleton-row)');
        rows.forEach(row => {
            const chk = row.querySelector('.item-checkbox');
            const btn = row.querySelector('.btn-inline-add');
            const qtyInput = row.querySelector('.inline-qty-input');
            if(chk) {
                chk.checked = isChecked;
                const id = chk.getAttribute('data-id');
                const name = chk.getAttribute('data-name');
                const price = chk.getAttribute('data-price');
                let qty = parseInt(qtyInput.value) || 1;
                handleProductSelection(id, name, price, isChecked, row, btn, false, qty);
            }
        });
        if(isChecked) showToast(`${rows.length} productos agregados`);
    });
}

const searchInp = document.getElementById('searchInput');
if (searchInp) searchInp.addEventListener('input', applyFilters);
const sortSel = document.getElementById('sortSelect');
if (sortSel) sortSel.addEventListener('change', applyFilters);
const unitSel = document.getElementById('unitSelect');
if (unitSel) unitSel.addEventListener('change', applyFilters);

const filterBtns = document.querySelectorAll('.filter-pill');
filterBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
        filterBtns.forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        currentCategory = e.target.getAttribute('data-filter');
        applyFilters();
    });
});

const prevBtn = document.getElementById('prevBtn');
if (prevBtn) { prevBtn.addEventListener('click', () => { if(currentPage > 1) { currentPage--; renderTable(); scrollUp(); } }); }
const nextBtn = document.getElementById('nextBtn');
if (nextBtn) { nextBtn.addEventListener('click', () => { if(currentPage < Math.ceil(filteredProducts.length / itemsPerPage)) { currentPage++; renderTable(); scrollUp(); } }); }

function scrollUp() { 
    const sec = document.querySelector('.catalog-section');
    if(sec) sec.scrollIntoView({ behavior: 'smooth', block: 'start' }); 
}

function showToast(message) {
    const container = document.getElementById('toast-container');
    if(!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg> <span>${message}</span>`;
    container.appendChild(toast);

    setTimeout(() => { toast.classList.add('fade-out'); }, 1200);
    setTimeout(() => { toast.remove(); }, 1500);
}

function setupAuthListeners() {
    const closeBtns = document.querySelectorAll('.close-modal-btn');
    closeBtns.forEach(btn => {
        btn.addEventListener('click', (e) => { 
            const overlay = e.target.closest('.saas-modal-overlay');
            if(overlay) overlay.classList.add('hidden'); 
        });
    });
}
